if ( ! defined( 'ABSPATH' ) ) { exit; } $a = is_array( $attributes ?? null ) ? $attributes : array(); $pick = static function( $v, $list, $d ) { return in_array( $v, $list, true ) ? $v : $d; }; $style = $pick( $a['style'] ?? 'soft', array( 'soft', 'solid', 'outline' ), 'soft' ); $tone = $pick( $a['tone'] ?? 'brand', array( 'brand', 'navy', 'success', 'warning', 'danger', 'neutral' ), 'brand' ); $size = $pick( $a['size'] ?? 'medium', array( 'small', 'medium', 'large' ), 'medium' ); $align = $pick( $a['align'] ?? 'left', array( 'left', 'center', 'right' ), 'left' ); $symbols = array( 'star' => '★ ', 'check' => '✓ ', 'spark' => '✦ ' ); $symbol = $symbols[ $a['icon'] ?? 'none' ] ?? ''; $badge = '<span class="bigspy-badge bigspy-badge--' . esc_attr( $style . ' bigspy-badge--' . $tone . ' bigspy-badge--' . $size ) . '">' . esc_html( $symbol ) . esc_html( wp_strip_all_tags( $a['text'] ?? 'New' ) ) . '</span>'; if ( ! empty( $a['url'] ) ) $badge = '<a class="bigspy-badge-link" href="' . esc_url( $a['url'] ) . '">' . $badge . '</a>'; echo '<div ' . get_block_wrapper_attributes( array( 'class' => 'bigspy-badge-wrap bigspy-badge-wrap--' . $align ) ) . '>' . $badge . '</div>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped